static void SpatialMaxPoolWithArgMaxHelper(
    OpKernelContext* context, Tensor* output, Tensor* output_arg_max,
    Tensor* input_backprop, const Tensor& tensor_in, const Tensor& out_backprop,
    const PoolParameters& params, const bool include_batch_in_index) {
  if (input_backprop != nullptr) {
    OP_REQUIRES(
        context, include_batch_in_index,
        errors::Internal(
            "SpatialMaxPoolWithArgMaxHelper requires include_batch_in_index "
            "to be True when input_backprop != nullptr"));
    OP_REQUIRES(
        context, (std::is_same<Targmax, int64>::value),
        errors::Internal("SpatialMaxPoolWithArgMaxHelper requires Targmax "
                         "to be int64 when input_backprop != nullptr"));
  }

  typedef Eigen::Map<const Eigen::Matrix<T, Eigen::Dynamic, Eigen::Dynamic>>
      ConstEigenMatrixMap;
  typedef Eigen::Map<Eigen::Matrix<T, Eigen::Dynamic, Eigen::Dynamic>>
      EigenMatrixMap;
  typedef Eigen::Map<Eigen::Matrix<Targmax, Eigen::Dynamic, Eigen::Dynamic>>
      EigenIndexMatrixMap;

  ConstEigenMatrixMap in_mat(
      tensor_in.flat<T>().data(), params.depth,
      params.tensor_in_cols * params.tensor_in_rows * params.tensor_in_batch);
  EigenMatrixMap out_mat(
      output->flat<T>().data(), params.depth,
      params.out_width * params.out_height * params.tensor_in_batch);
  EigenIndexMatrixMap out_arg_max_mat(
      output_arg_max->flat<Targmax>().data(), params.depth,
      params.out_width * params.out_height * params.tensor_in_batch);

  const DeviceBase::CpuWorkerThreads& worker_threads =
      *(context->device()->tensorflow_cpu_worker_threads());

  // The following code basically does the following:
  // 1. Flattens the input and output tensors into two dimensional arrays.
  //    tensor_in_as_matrix:
  //      depth by (tensor_in_cols * tensor_in_rows * tensor_in_batch)
  //    output_as_matrix:
  //      depth by (out_width * out_height * tensor_in_batch)
  //
  // 2. Walks through the set of columns in the flattened tensor_in_as_matrix,
  //    and updates the corresponding column(s) in output_as_matrix with the
  //    max value.
  auto shard = [&params, &in_mat, &out_mat, &out_arg_max_mat, &input_backprop,
                &output_arg_max, &out_backprop,
                include_batch_in_index](int64 start, int64 limit) {
    const int32 depth = params.depth;
    const int32 in_rows = params.tensor_in_rows;
    const int32 in_cols = params.tensor_in_cols;
    const int32 pad_top = params.pad_top;
    const int32 pad_left = params.pad_left;
    const int32 window_rows = params.window_rows;
    const int32 window_cols = params.window_cols;
    const int32 row_stride = params.row_stride;
    const int32 col_stride = params.col_stride;
    const int32 out_height = params.out_height;
    const int32 out_width = params.out_width;

    {
      // Initializes the output tensor with MIN<T>.
      const int32 output_image_size = out_height * out_width * depth;
      EigenMatrixMap out_shard(out_mat.data() + start * output_image_size, 1,
                               (limit - start) * output_image_size);
      out_shard.setConstant(Eigen::NumTraits<T>::lowest());
      EigenIndexMatrixMap out_arg_max_shard(
          out_arg_max_mat.data() + start * output_image_size, 1,
          (limit - start) * output_image_size);
      out_arg_max_shard.setConstant(kInvalidMaxPoolingIndex);
    }

    for (int64 b = start; b < limit; ++b) {
      for (int h = 0; h < in_rows; ++h) {
        for (int w = 0; w < in_cols; ++w) {
          // (h_start, h_end) * (w_start, w_end) is the range that the input
          // vector projects to.
          const int hpad = h + pad_top;
          const int wpad = w + pad_left;
          const int h_start =
              (hpad < window_rows) ? 0 : (hpad - window_rows) / row_stride + 1;
          const int h_end = std::min(hpad / row_stride + 1, out_height);
          const int w_start =
              (wpad < window_cols) ? 0 : (wpad - window_cols) / col_stride + 1;
          const int w_end = std::min(wpad / col_stride + 1, out_width);
          // compute elementwise max
          const int64 in_index = (b * in_rows + h) * in_cols + w;
          for (int ph = h_start; ph < h_end; ++ph) {
            const int64 out_index_base = (b * out_height + ph) * out_width;
            for (int pw = w_start; pw < w_end; ++pw) {
              const int64 out_index = out_index_base + pw;
              /// NOTES(zhengxq): not using the eigen matrix operation for
              /// now.
              for (int d = 0; d < depth; ++d) {
                const T& input_ref = in_mat.coeffRef(d, in_index);
                T& output_ref = out_mat.coeffRef(d, out_index);
                Targmax& out_arg_max_ref =
                    out_arg_max_mat.coeffRef(d, out_index);
                if (output_ref < input_ref ||
                    out_arg_max_ref == kInvalidMaxPoolingIndex) {
                  output_ref = input_ref;
                  if (include_batch_in_index) {
                    out_arg_max_ref = in_index * depth + d;
                  } else {
                    out_arg_max_ref = (h * in_cols + w) * depth + d;
                  }
                }
              }
            }
          }
        }
      }
    }

    if (input_backprop != nullptr) {
      auto input_backprop_flat = input_backprop->flat<T>();
      auto out_arg_max_flat = output_arg_max->flat<int64>();
      auto out_backprop_flat = out_backprop.flat<T>();

      // Initialize output to 0.
      const int64 in_size = in_rows * in_cols * depth;
      const int64 in_start = start * in_size;
      const int64 in_end = limit * in_size;
      EigenMatrixMap in_shard(input_backprop_flat.data() + in_start, 1,
                              in_end - in_start);
      in_shard.setConstant(T(0));

      // Backpropagate.
      const int out_size = out_height * out_width * depth;
      const int out_start = start * out_size;
      const int out_end = limit * out_size;
      for (int index = out_start; index < out_end; ++index) {
        int input_backprop_index = out_arg_max_flat(index);
        // Although this check is in the inner loop, it is worth its value
        // so we don't end up with memory corruptions. Our benchmark shows that
        // the performance impact is quite small
        // CHECK(input_backprop_index >= in_start && input_backprop_index <
        // in_end)
        FastBoundsCheck(input_backprop_index - in_start, in_end - in_start);
        if (index < out_backprop.NumElements()) {
          input_backprop_flat(input_backprop_index) += out_backprop_flat(index);
        }
      }
    }
  };

  const int64 shard_cost = params.tensor_in_rows * params.tensor_in_cols *
                           params.depth * params.window_rows *
                           params.window_cols;
  Shard(worker_threads.num_threads, worker_threads.workers,
        params.tensor_in_batch, shard_cost, shard);
}

parseNormalModeParameters(IsoPresentation* self, uint8_t* buffer, int totalLength, int bufPos)
{
    int endPos = bufPos + totalLength;

    self->calledPresentationSelector.size = 0;
    self->callingPresentationSelector.size = 0;

    bool hasUserData = false;

    while (bufPos < endPos) {
        uint8_t tag = buffer[bufPos++];
        int len;

        if (bufPos == endPos) {
            if (DEBUG_PRES)
                printf("PRES: invalid message\n");
            return -1;
        }

        bufPos = BerDecoder_decodeLength(buffer, &len, bufPos, endPos);

        if (bufPos < 0) {
            if (DEBUG_PRES)
                printf("PRES: wrong parameter length\n");
            return -1;
        }

        switch (tag) {
        case 0x81: /* calling-presentation-selector */

            if (len > 16) {
                if (DEBUG_PRES)
                    printf("PRES: calling-presentation-sel too large\n");
            }
            else {
                self->callingPresentationSelector.size = len;
                int i;
                for (i = 0; i < len; i++)
                    self->callingPresentationSelector.value[i] = buffer[bufPos + i];
            }

            bufPos += len;
            break;

        case 0x82: /* called-presentation-selector */

            if (len > 16) {
                if (DEBUG_PRES)
                    printf("PRES: called-presentation-sel too large\n");
            }
            else {
                self->calledPresentationSelector.size = len;
                int i;
                for (i = 0; i < len; i++)
                    self->calledPresentationSelector.value[i] = buffer[bufPos + i];
            }

            bufPos += len;
            break;

        case 0x83: /* responding-presentation-selector */

            if (len > 16) {
                if (DEBUG_PRES)
                    printf("PRES: responding-presentation-sel too large\n");
            }

            bufPos += len;
            break;

        case 0xa4: /* presentation-context-definition list */
            if (DEBUG_PRES)
                printf("PRES: pcd list\n");
            bufPos = parsePresentationContextDefinitionList(self, buffer, len, bufPos);

            if (bufPos < 0)
                return -1;

            break;

        case 0xa5: /* context-definition-result-list */

            bufPos += len;
            break;

        case 0x61: /* user data */
            if (DEBUG_PRES)
                printf("PRES: user-data\n");

            bufPos = parseFullyEncodedData(self, buffer, len, bufPos);

            if (bufPos < 0)
                return -1;

            if (self->nextPayload.size > 0)
                hasUserData = true;

            break;

        case 0x00: /* indefinite length end tag -> ignore */
            break;

        default:
            if (DEBUG_PRES)
                printf("PRES: unknown tag in normal-mode\n");
            bufPos += len;
            break;
        }
    }

    if (hasUserData == false) {
        if (DEBUG_PRES)
            printf("PRES: user-data is missing\n");

        return -1;
    }

    return bufPos;
}

void Compute(OpKernelContext* ctx) override {
  const Tensor& shape_tensor = ctx->input(0);
  const Tensor& means_tensor = ctx->input(1);
  const Tensor& stddevs_tensor = ctx->input(2);
  const Tensor& minvals_tensor = ctx->input(3);
  const Tensor& maxvals_tensor = ctx->input(4);

  OP_REQUIRES(
      ctx, TensorShapeUtils::IsVector(shape_tensor.shape()),
      errors::InvalidArgument("Input shape should be a vector, got shape: ",
                              shape_tensor.shape().DebugString()));
  int32 num_batches = shape_tensor.flat<int32>()(0);

  int32 samples_per_batch = 1;
  const int32 num_dims = shape_tensor.dim_size(0);
  for (int32 i = 1; i < num_dims; i++) {
    samples_per_batch *= shape_tensor.flat<int32>()(i);
  }
  const int32 num_elements = num_batches * samples_per_batch;

  // Allocate the output before fudging num_batches and samples_per_batch.
  auto shape_vec = shape_tensor.flat<int32>();
  TensorShape tensor_shape;
  OP_REQUIRES_OK(ctx, TensorShapeUtils::MakeShape(
                          shape_vec.data(), shape_vec.size(), &tensor_shape));
  Tensor* samples_tensor;
  OP_REQUIRES_OK(ctx, ctx->allocate_output(0, tensor_shape, &samples_tensor));

  // Parameters must be 0-d or 1-d.
  OP_REQUIRES(ctx, means_tensor.dims() <= 1,
              errors::InvalidArgument(
                  "Input means should be a scalar or vector, got shape: ",
                  means_tensor.shape().DebugString()));
  OP_REQUIRES(ctx, stddevs_tensor.dims() <= 1,
              errors::InvalidArgument(
                  "Input stddevs should be a scalar or vector, got shape: ",
                  stddevs_tensor.shape().DebugString()));
  OP_REQUIRES(ctx, minvals_tensor.dims() <= 1,
              errors::InvalidArgument(
                  "Input minvals should be a scalar or vector, got shape: ",
                  minvals_tensor.shape().DebugString()));
  OP_REQUIRES(ctx, maxvals_tensor.dims() <= 1,
              errors::InvalidArgument(
                  "Input maxvals should be a scalar or vector, got shape: ",
                  maxvals_tensor.shape().DebugString()));

  if ((means_tensor.dims() == 0 || means_tensor.dim_size(0) == 1) &&
      (stddevs_tensor.dims() == 0 || stddevs_tensor.dim_size(0) == 1) &&
      minvals_tensor.dims() == 0 && maxvals_tensor.dims() == 0) {
    // All batches have the same parameters, so we can update the batch size
    // to a reasonable value to improve parallelism (ensure enough batches,
    // and no very small batches which have high overhead).
    int32 size = num_batches * samples_per_batch;
    int32 adjusted_samples = kDesiredBatchSize;
    // Ensure adjusted_batches * adjusted_samples >= size.
    int32 adjusted_batches = Eigen::divup(size, adjusted_samples);
    num_batches = adjusted_batches;
    samples_per_batch = adjusted_samples;
  } else {
    // Parameters must be broadcastable to the shape [num_batches].
    OP_REQUIRES(
        ctx,
        TensorShapeUtils::IsScalar(means_tensor.shape()) ||
            means_tensor.dim_size(0) == 1 ||
            means_tensor.dim_size(0) == num_batches,
        errors::InvalidArgument(
            "Input means should have length 1 or shape[0], got shape: ",
            means_tensor.shape().DebugString()));
    OP_REQUIRES(
        ctx,
        TensorShapeUtils::IsScalar(stddevs_tensor.shape()) ||
            stddevs_tensor.dim_size(0) == 1 ||
            stddevs_tensor.dim_size(0) == num_batches,
        errors::InvalidArgument(
            "Input stddevs should have length 1 or shape[0], got shape: ",
            stddevs_tensor.shape().DebugString()));
    OP_REQUIRES(
        ctx,
        TensorShapeUtils::IsScalar(minvals_tensor.shape()) ||
            minvals_tensor.dim_size(0) == 1 ||
            minvals_tensor.dim_size(0) == num_batches,
        errors::InvalidArgument(
            "Input minvals should have length 1 or shape[0], got shape: ",
            minvals_tensor.shape().DebugString()));
    OP_REQUIRES(
        ctx,
        TensorShapeUtils::IsScalar(maxvals_tensor.shape()) ||
            maxvals_tensor.dim_size(0) == 1 ||
            maxvals_tensor.dim_size(0) == num_batches,
        errors::InvalidArgument(
            "Input maxvals should have length 1 or shape[0], got shape: ",
            maxvals_tensor.shape().DebugString()));
  }

  auto truncFunctor = functor::TruncatedNormalFunctor<Device, T>();
  // Each worker has the fudge factor for samples_per_batch, so use it here.
  random::PhiloxRandom rng =
      generator_.ReserveSamples128(num_batches * 2 * functor::kMaxIterations *
                                   (samples_per_batch + 3) / 4);
  truncFunctor(ctx, ctx->eigen_device<Device>(), num_batches,
               samples_per_batch, num_elements, means_tensor.flat<T>(),
               stddevs_tensor.flat<T>(), minvals_tensor.flat<T>(),
               maxvals_tensor.flat<T>(), rng, samples_tensor->flat<T>());
}

static chunk * connection_read_header_more(connection *con, chunkqueue *cq, chunk *c, const size_t olen) {
    /*(should not be reached by HTTP/2 streams)*/
    /*if (r->http_version == HTTP_VERSION_2) return NULL;*/
    /*(However, new connections over TLS may become HTTP/2 connections via ALPN
     * and return from this routine with r->http_version == HTTP_VERSION_2) */

    if ((NULL == c || NULL == c->next) && con->is_readable > 0) {
        con->read_idle_ts = log_epoch_secs;
        if (0 != con->network_read(con, cq, MAX_READ_LIMIT)) {
            request_st * const r = &con->request;
            connection_set_state_error(r, CON_STATE_ERROR);
        }
        /* check if switched to HTTP/2 (ALPN "h2" during TLS negotiation) */
        request_st * const r = &con->request;
        if (r->http_version == HTTP_VERSION_2) return NULL;
    }

    if (cq->first != cq->last && 0 != olen) {
        const size_t clen = chunkqueue_length(cq);
        size_t block = (olen + (16384-1)) & ~(16384-1);
        block += (block - olen > 1024 ? 0 : 16384);
        chunkqueue_compact_mem(cq, block > clen ? clen : block);
    }

    /* detect if data is added to chunk */
    c = cq->first;
    return (c && (size_t)c->offset + olen < buffer_string_length(c->mem))
      ? c
      : NULL;
}

void Compute(OpKernelContext* ctx) override {
  const Tensor& shape_tensor = ctx->input(0);
  const Tensor& means_tensor = ctx->input(1);
  const Tensor& stddevs_tensor = ctx->input(2);
  const Tensor& minvals_tensor = ctx->input(3);
  const Tensor& maxvals_tensor = ctx->input(4);

  OP_REQUIRES(
      ctx, TensorShapeUtils::IsVector(shape_tensor.shape()),
      errors::InvalidArgument("Input shape should be a vector, got shape: ",
                              shape_tensor.shape().DebugString()));
  OP_REQUIRES(ctx, shape_tensor.NumElements() > 0,
              errors::InvalidArgument("Shape tensor must not be empty, got ",
                                      shape_tensor.DebugString()));
  int32 num_batches = shape_tensor.flat<int32>()(0);

  int32 samples_per_batch = 1;
  const int32 num_dims = shape_tensor.dim_size(0);
  for (int32 i = 1; i < num_dims; i++) {
    samples_per_batch *= shape_tensor.flat<int32>()(i);
  }
  const int32 num_elements = num_batches * samples_per_batch;

  // Allocate the output before fudging num_batches and samples_per_batch.
  auto shape_vec = shape_tensor.flat<int32>();
  TensorShape tensor_shape;
  OP_REQUIRES_OK(ctx, TensorShapeUtils::MakeShape(
                          shape_vec.data(), shape_vec.size(), &tensor_shape));
  Tensor* samples_tensor;
  OP_REQUIRES_OK(ctx, ctx->allocate_output(0, tensor_shape, &samples_tensor));

  // Parameters must be 0-d or 1-d.
  OP_REQUIRES(ctx, means_tensor.dims() <= 1,
              errors::InvalidArgument(
                  "Input means should be a scalar or vector, got shape: ",
                  means_tensor.shape().DebugString()));
  OP_REQUIRES(ctx, stddevs_tensor.dims() <= 1,
              errors::InvalidArgument(
                  "Input stddevs should be a scalar or vector, got shape: ",
                  stddevs_tensor.shape().DebugString()));
  OP_REQUIRES(ctx, minvals_tensor.dims() <= 1,
              errors::InvalidArgument(
                  "Input minvals should be a scalar or vector, got shape: ",
                  minvals_tensor.shape().DebugString()));
  OP_REQUIRES(ctx, maxvals_tensor.dims() <= 1,
              errors::InvalidArgument(
                  "Input maxvals should be a scalar or vector, got shape: ",
                  maxvals_tensor.shape().DebugString()));

  if ((means_tensor.dims() == 0 || means_tensor.dim_size(0) == 1) &&
      (stddevs_tensor.dims() == 0 || stddevs_tensor.dim_size(0) == 1) &&
      minvals_tensor.dims() == 0 && maxvals_tensor.dims() == 0) {
    // All batches have the same parameters, so we can update the batch size
    // to a reasonable value to improve parallelism (ensure enough batches,
    // and no very small batches which have high overhead).
    int32 size = num_batches * samples_per_batch;
    int32 adjusted_samples = kDesiredBatchSize;
    // Ensure adjusted_batches * adjusted_samples >= size.
    int32 adjusted_batches = Eigen::divup(size, adjusted_samples);
    num_batches = adjusted_batches;
    samples_per_batch = adjusted_samples;
  } else {
    // Parameters must be broadcastable to the shape [num_batches].
    OP_REQUIRES(
        ctx,
        TensorShapeUtils::IsScalar(means_tensor.shape()) ||
            means_tensor.dim_size(0) == 1 ||
            means_tensor.dim_size(0) == num_batches,
        errors::InvalidArgument(
            "Input means should have length 1 or shape[0], got shape: ",
            means_tensor.shape().DebugString()));
    OP_REQUIRES(
        ctx,
        TensorShapeUtils::IsScalar(stddevs_tensor.shape()) ||
            stddevs_tensor.dim_size(0) == 1 ||
            stddevs_tensor.dim_size(0) == num_batches,
        errors::InvalidArgument(
            "Input stddevs should have length 1 or shape[0], got shape: ",
            stddevs_tensor.shape().DebugString()));
    OP_REQUIRES(
        ctx,
        TensorShapeUtils::IsScalar(minvals_tensor.shape()) ||
            minvals_tensor.dim_size(0) == 1 ||
            minvals_tensor.dim_size(0) == num_batches,
        errors::InvalidArgument(
            "Input minvals should have length 1 or shape[0], got shape: ",
            minvals_tensor.shape().DebugString()));
    OP_REQUIRES(
        ctx,
        TensorShapeUtils::IsScalar(maxvals_tensor.shape()) ||
            maxvals_tensor.dim_size(0) == 1 ||
            maxvals_tensor.dim_size(0) == num_batches,
        errors::InvalidArgument(
            "Input maxvals should have length 1 or shape[0], got shape: ",
            maxvals_tensor.shape().DebugString()));
  }

  auto truncFunctor = functor::TruncatedNormalFunctor<Device, T>();
  // Each worker has the fudge factor for samples_per_batch, so use it here.
  random::PhiloxRandom rng =
      generator_.ReserveSamples128(num_batches * 2 * functor::kMaxIterations *
                                   (samples_per_batch + 3) / 4);
  truncFunctor(ctx, ctx->eigen_device<Device>(), num_batches,
               samples_per_batch, num_elements, means_tensor.flat<T>(),
               stddevs_tensor.flat<T>(), minvals_tensor.flat<T>(),
               maxvals_tensor.flat<T>(), rng, samples_tensor->flat<T>());
}

