static int parse_dirfile(char *buf, size_t nbytes, struct file *file,
			 struct dir_context *ctx)
{
	while (nbytes >= FUSE_NAME_OFFSET) {
		struct fuse_dirent *dirent = (struct fuse_dirent *) buf;
		size_t reclen = FUSE_DIRENT_SIZE(dirent);
		if (!dirent->namelen || dirent->namelen > FUSE_NAME_MAX)
			return -EIO;
		if (reclen > nbytes)
			break;
		if (memchr(dirent->name, '/', dirent->namelen) != NULL)
			return -EIO;

		if (!fuse_emit(file, ctx, dirent))
			break;

		buf += reclen;
		nbytes -= reclen;
		ctx->pos = dirent->off;
	}

	return 0;
}

static req::ptr<Key> GetHelper(const Variant& var, bool public_key,
                               const char *passphrase) {
  req::ptr<Certificate> ocert;
  EVP_PKEY *key = nullptr;

  if (var.isResource()) {
    auto cert = dyn_cast_or_null<Certificate>(var);
    auto key = dyn_cast_or_null<Key>(var);
    if (!cert && !key) return nullptr;
    if (key) {
      bool is_priv = key->isPrivate();
      if (!public_key && !is_priv) {
        raise_warning("supplied key param is a public key");
        return nullptr;
      }
      if (public_key && is_priv) {
        raise_warning("Don't know how to get public key from "
                        "this private key");
        return nullptr;
      }
      return key;
    }
    ocert = cert;
  } else {
    /* it's an X509 file/cert of some kind, and we need to extract
       the data from that */
    if (public_key) {
      ocert = Certificate::Get(var);
      if (!ocert) {
        /* not a X509 certificate, try to retrieve public key */
        BIO *in = Certificate::ReadData(var);
        if (in == nullptr) return nullptr;
        key = PEM_read_bio_PUBKEY(in, nullptr,nullptr, nullptr);
        BIO_free(in);
      }
    } else {
      /* we want the private key */
      BIO *in = Certificate::ReadData(var);
      if (in == nullptr) return nullptr;
      key = PEM_read_bio_PrivateKey(in, nullptr,nullptr, (void*)passphrase);
      BIO_free(in);
    }
  }

  if (public_key && ocert && key == nullptr) {
    /* extract public key from X509 cert */
    key = (EVP_PKEY *)X509_get_pubkey(ocert->get());
  }

  if (key) {
    return req::make<Key>(key);
  }

  return nullptr;
}

sc_oberthur_get_certificate_authority(struct sc_pkcs15_der *der, int *out_authority)
{
#ifdef ENABLE_OPENSSL
	X509	*x;
	BUF_MEM buf_mem;
	BIO *bio = NULL;
	BASIC_CONSTRAINTS *bs = NULL;

	if (!der)
		return SC_ERROR_INVALID_ARGUMENTS;

	buf_mem.data = malloc(der->len);
	if (!buf_mem.data)
		return SC_ERROR_OUT_OF_MEMORY;

	memcpy(buf_mem.data, der->value, der->len);
	buf_mem.max = buf_mem.length = der->len;

	bio = BIO_new(BIO_s_mem());
	if (!bio) {
		free(buf_mem.data);
		return SC_ERROR_OUT_OF_MEMORY;
	}

	BIO_set_mem_buf(bio, &buf_mem, BIO_NOCLOSE);
	x = d2i_X509_bio(bio, 0);
	BIO_free(bio);
	if (!x)
		return SC_ERROR_INVALID_DATA;

	bs = (BASIC_CONSTRAINTS *)X509_get_ext_d2i(x, NID_basic_constraints, NULL, NULL);
	if (out_authority)
		*out_authority = (bs && bs->ca);

	X509_free(x);

	return SC_SUCCESS;
#else
	return SC_ERROR_NOT_SUPPORTED;
#endif
}

